<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';
require_once __DIR__.'/_helper.php';
bk_require_access($pdo);
if(user_role()==='kepala_sekolah'){http_response_code(403);exit('Detail riwayat layanan BK tidak tersedia untuk role Kepala Sekolah.');}
$q=trim((string)($_GET['q']??''));
$jenis=(string)($_GET['jenis']??'');
$from=(string)($_GET['from']??'');
$to=(string)($_GET['to']??'');
$perPageInput=(int)($_GET['per_page']??20);$perPage=in_array($perPageInput,[10,20,50,100],true)?$perPageInput:20;
$page=max(1,(int)($_GET['page']??1));
$where=['1=1'];$params=[];
if($q!==''){ $like='%'.$q.'%';$where[]='(s.nama LIKE ? OR s.nis LIKE ? OR s.nisn LIKE ? OR bl.topik LIKE ?)';array_push($params,$like,$like,$like,$like); }
if(in_array($jenis,['konseling','konsultasi','rujukan','administratif','lainnya'],true)){ $where[]='bl.jenis_layanan=?';$params[]=$jenis; }
if($from!=='' && preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){ $where[]='bl.tanggal>=?';$params[]=$from; }
if($to!=='' && preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){ $where[]='bl.tanggal<=?';$params[]=$to; }
if(user_role()==='guru_bk'){ $gid=bk_current_guru_id($pdo);$where[]='bl.petugas_id=?';$params[]=$gid; }
$count=$pdo->prepare('SELECT COUNT(*) FROM bk_layanan bl JOIN siswa s ON s.id=bl.siswa_id WHERE '.implode(' AND ',$where));$count->execute($params);$total=(int)$count->fetchColumn();
$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$sql='SELECT bl.id,bl.nomor_antrian,bl.tanggal,bl.waktu_masuk,bl.waktu_mulai,bl.waktu_selesai,bl.status,bl.jenis_layanan,bl.topik,bl.petugas_id,s.nis,s.nisn,s.nama,mk.nama AS kelas,g.nama AS petugas FROM bk_layanan bl JOIN siswa s ON s.id=bl.siswa_id LEFT JOIN master_kelas mk ON mk.id=bl.kelas_id LEFT JOIN guru g ON g.id=bl.petugas_id WHERE '.implode(' AND ',$where).' ORDER BY bl.tanggal DESC,bl.nomor_antrian DESC LIMIT '.$perPage.' OFFSET '.$offset;
$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
function layanan_query(array $changes=[]):string{$base=$_GET??[];unset($base['page']);foreach($changes as $k=>$v){if($v===null)unset($base[$k]);else$base[$k]=$v;}return http_build_query($base);}
$page_title='Riwayat Layanan BK';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?>
