<div class="table-responsive" style="margin-top:16px"><table class="data-table"><thead><tr><th>Tanggal</th><th>No.</th><th>Siswa</th><th>Kelas</th><th>Keperluan</th><th>Petugas</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="8" class="empty-state">Belum ada riwayat layanan sesuai filter.</td></tr><?php else: foreach($rows as $r): ?><tr><td><?=e($r['tanggal'])?><div style="font-size:11px;color:#64748b"><?=e(substr((string)$r['waktu_masuk'],11,5))?> WIB</div></td><td><strong>#<?=e((string)$r['nomor_antrian'])?></strong></td><td><strong><?=e($r['nama'])?></strong><div style="font-size:11px;color:#64748b"><?=e($r['nis'])?><?=!empty($r['nisn'])?' · '.e($r['nisn']):''?></div></td><td><?=e($r['kelas']??'-')?></td><td><?=e($r['jenis_layanan']??'-')?></td><td><?=e($r['petugas']??'-')?></td><td><span class="bk-status bk-status-<?=e($r['status'])?>"><?=e(strtoupper($r['status']))?></span></td><td><a class="btn btn-sm btn-secondary" href="<?=BASE_URL?>bk/layanan_detail.php?id=<?=$r['id']?>" title="Detail layanan"><i class="bi bi-eye"></i></a></td></tr><?php endforeach; endif;?></tbody></table></div>
<?php if($pages>1): ?><div class="bk-pagination"><div style="font-size:12px;color:#64748b">Halaman <?=$page?> dari <?=$pages?> · <?=number_format($total)?> layanan</div><div class="bk-pages"><?php if($page>1): ?><a href="?<?=e( layanan_query(['page'=>$page-1]) )?>"><i class="bi bi-chevron-left"></i></a><?php endif;?><?php $start=max(1,$page-2);$end=min($pages,$page+2);for($pp=$start;$pp<=$end;$pp++): ?><a class="<?=$pp===$page?'active':''?>" href="?<?=e(layanan_query(['page'=>$pp]))?>"><?=$pp?></a><?php endfor;?><?php if($page<$pages): ?><a href="?<?=e(layanan_query(['page'=>$page+1]))?>"><i class="bi bi-chevron-right"></i></a><?php endif;?></div></div><?php endif;?></div>
